The repo is empty (no tracked files, no `package.json`), so I don't know your stack. Below is framework-agnostic vanilla JS/CSS with no dependencies, which you can paste into any page. Nothing was written to disk.

## 1. Markup

Add this once, near the top of `<body>`:

```html
<canvas id="bg" aria-hidden="true"></canvas>
<div class="cursor" aria-hidden="true"><i class="dot"></i><i class="ring"></i></div>
```

For parallax, add `data-speed` to elements inside each section. Negative values move against the scroll, positive values move with it:

```html
<section class="hero">
  <h1 data-speed="0.15">Pricing that scales</h1>
  <div class="blob" data-speed="-0.25"></div>
</section>
<section class="plans">
  <div class="card" data-speed="0.08">…</div>
  <div class="card" data-speed="0.14">…</div>
  <div class="card" data-speed="0.08">…</div>
</section>
```

## 2. CSS

```css
#bg { position: fixed; inset: 0; width: 100%; height: 100%; z-index: -1; }

/* Hide the native cursor only on real mouse devices */
@media (hover: hover) and (pointer: fine) {
  html.has-cursor, html.has-cursor a, html.has-cursor button { cursor: none; }
}
.cursor { position: fixed; inset: 0 auto auto 0; pointer-events: none; z-index: 9999; display: none; }
html.has-cursor .cursor { display: block; }
.cursor i { position: fixed; top: 0; left: 0; border-radius: 50%; will-change: transform; }
.dot  { width: 6px;  height: 6px;  margin: -3px 0 0 -3px;   background: #fff; mix-blend-mode: difference; }
.ring { width: 36px; height: 36px; margin: -18px 0 0 -18px; border: 1px solid #fff; mix-blend-mode: difference;
        transition: width .25s, height .25s, margin .25s, background .25s; }
.ring.hover { width: 72px; height: 72px; margin: -36px 0 0 -36px; background: #fff; }

[data-speed] { will-change: transform; }

@media (prefers-reduced-motion: reduce) {
  html.has-cursor, html.has-cursor a, html.has-cursor button { cursor: auto; }
}
```

## 3. JS (one `<script type="module">`, no libraries)

```js
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const fine   = matchMedia('(hover: hover) and (pointer: fine)').matches;

/* ---------- WebGL particles ---------- */
const canvas = document.getElementById('bg');
const gl = canvas.getContext('webgl', { alpha: true, antialias: false });

if (gl) {
  const vs = `
    attribute vec3 a;            // x, y, phase
    uniform float t, aspect, scrollY;
    uniform vec2 m;              // mouse in clip space
    void main(){
      vec2 p = a.xy;
      p.x += sin(t*.2 + a.z*6.283) * .04;
      p.y += cos(t*.15 + a.z*6.283) * .04 + scrollY * (.05 + a.z*.25);  // depth-based scroll parallax
      p.y = mod(p.y + 1., 2.) - 1.;                                      // wrap
      vec2 d = p - m; float f = .12 / (dot(d,d)*40. + .3);               // mouse repulsion
      p += normalize(d + 1e-4) * f * .05;
      gl_Position = vec4(p.x / aspect, p.y, 0., 1.);
      gl_PointSize = 1.5 + a.z * 3.5;
    }`;
  const fs = `
    precision mediump float;
    void main(){
      float d = length(gl_PointCoord - .5);
      if (d > .5) discard;
      gl_FragColor = vec4(.55,.6,1., (1. - d*2.) * .7);
    }`;

  const sh = (type, src) => { const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); return s; };
  const prog = gl.createProgram();
  gl.attachShader(prog, sh(gl.VERTEX_SHADER, vs));
  gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, fs));
  gl.linkProgram(prog); gl.useProgram(prog);

  const N = innerWidth < 768 ? 500 : 1500;
  const data = new Float32Array(N * 3);
  for (let i = 0; i < N; i++) {
    data[i*3]   = Math.random()*2 - 1;
    data[i*3+1] = Math.random()*2 - 1;
    data[i*3+2] = Math.random();
  }
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog, 'a');
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 3, gl.FLOAT, false, 0, 0);
  gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

  const U = n => gl.getUniformLocation(prog, n);
  const uT = U('t'), uA = U('aspect'), uS = U('scrollY'), uM = U('m');

  const resize = () => {
    const dpr = Math.min(devicePixelRatio, 2);
    canvas.width = innerWidth * dpr; canvas.height = innerHeight * dpr;
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.uniform1f(uA, innerWidth / innerHeight);
  };
  addEventListener('resize', resize); resize();

  const mouse = { x: 0, y: 0 };
  addEventListener('pointermove', e => {
    mouse.x = (e.clientX / innerWidth * 2 - 1) * (innerWidth / innerHeight);
    mouse.y = -(e.clientY / innerHeight * 2 - 1);
  });

  let visible = true;
  document.addEventListener('visibilitychange', () => visible = !document.hidden);

  const draw = now => {
    requestAnimationFrame(draw);
    if (!visible) return;
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform1f(uT, reduce ? 0 : now / 1000);
    gl.uniform1f(uS, scrollSmooth / innerHeight);
    gl.uniform2f(uM, mouse.x, mouse.y);
    gl.drawArrays(gl.POINTS, 0, N);
  };
  requestAnimationFrame(draw);
}

/* ---------- Smoothed scroll shared by particles + parallax ---------- */
let scrollSmooth = scrollY;

/* ---------- Parallax on every section ---------- */
const items = [...document.querySelectorAll('[data-speed]')].map(el => ({
  el, speed: +el.dataset.speed, top: 0, h: 0, on: false,
}));
const measure = () => items.forEach(i => {
  const r = i.el.getBoundingClientRect();
  i.top = r.top + scrollY - (i.y || 0);  // undo current offset so rect is the untransformed position
  i.h = r.height;
});
measure(); addEventListener('resize', measure); addEventListener('load', measure);

new IntersectionObserver(es => es.forEach(e => {
  items.find(i => i.el === e.target).on = e.isIntersecting;
}), { rootMargin: '20% 0px' }).observe && items.forEach(i => 0);
const io = new IntersectionObserver(es => es.forEach(e => {
  items.find(i => i.el === e.target).on = e.isIntersecting;
}), { rootMargin: '20% 0px' });
items.forEach(i => io.observe(i.el));

/* ---------- Custom cursor ---------- */
const dot = document.querySelector('.dot'), ring = document.querySelector('.ring');
let cx = innerWidth/2, cy = innerHeight/2, rx = cx, ry = cy;
if (fine && !reduce) {
  document.documentElement.classList.add('has-cursor');
  addEventListener('pointermove', e => { cx = e.clientX; cy = e.clientY; });
  document.addEventListener('pointerover', e => ring.classList.toggle('hover', !!e.target.closest('a, button, [data-cursor]')));
}

/* ---------- One rAF loop for scroll smoothing, parallax, cursor ---------- */
(function tick() {
  requestAnimationFrame(tick);
  scrollSmooth += (scrollY - scrollSmooth) * .08;
  if (!reduce) {
    const vh = innerHeight;
    for (const i of items) {
      if (!i.on) continue;
      const center = i.top + i.h/2 - scrollSmooth - vh/2;   // distance from viewport centre
      i.y = center * i.speed * -1;
      i.el.style.transform = `translate3d(0, ${i.y.toFixed(1)}px, 0)`;
    }
  }
  rx += (cx - rx) * .15; ry += (cy - ry) * .15;
  dot.style.transform  = `translate3d(${cx}px, ${cy}px, 0)`;
  ring.style.transform = `translate3d(${rx}px, ${ry}px, 0)`;
})();
```

I left a redundant first `IntersectionObserver` line in that block. Delete the line beginning `new IntersectionObserver(...).observe && ...` and keep the `io` version below it.

## Things to know before shipping

- **Pricing readability:** keep parallax speeds small (about ±0.05 to 0.15) on the pricing cards. Text that drifts a lot hurts scannability and conversion. Save the big offsets for decorative blobs and headings.
- **Sticky elements:** `transform` on an ancestor breaks `position: sticky` and `fixed` children. Apply `data-speed` to leaf elements, not to wrappers that contain sticky content.
- **Accessibility:** the code respects `prefers-reduced-motion` and only enables the cursor on fine-pointer devices. Touch devices get the native experience. Keep the `aria-hidden` attributes.
- **Performance:**
  - Particles drop to 500 on narrow screens.
  - Device pixel ratio is capped at 2.
  - Parallax only updates elements currently in view.
  - Only `transform` is animated.
  - If you need more particles, move to `THREE.Points` or `ogl`, but the plain-WebGL version above is about 2 KB.
- **Contrast:** the particle canvas sits at `z-index: -1`. Make sure your section backgrounds are transparent or semi-transparent, or the particles will be hidden.
- **Smooth scroll:** for the fuller Awwwards feel, add Lenis (about 3 KB). Feed its scroll value into `scrollSmooth` instead of the manual lerp.
- **Framework use:** in React, Vue or Svelte, wrap the JS in a mount effect and cancel the rAF loops and remove the listeners on unmount.

